// Fails when src/lib/api/schema.d.ts is stale relative to docs/openapi.v1.json —
// the contract (generated by the server) is the single source of API types.
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const out = join(mkdtempSync(join(tmpdir(), "lf-api-")), "schema.d.ts");
execFileSync("npx", ["openapi-typescript", "../docs/openapi.v1.json", "-o", out], { stdio: "ignore" });
if (readFileSync(out, "utf8") !== readFileSync("src/lib/api/schema.d.ts", "utf8")) {
  console.error("src/lib/api/schema.d.ts is out of date — run `npm run gen:api`.");
  process.exit(1);
}
console.log("API types match docs/openapi.v1.json");
